        "| መለእኽክትንም ፣ በጨለማና ፡ በብርሃን ፡ አካል፡ | ላይ ፡ የተጀሙ ፡ መላአክትንም ፤ በውርጭና | በበረድ ፡ አክል ፡ ላይ ፡ የተሾሙ ፡ መላአክት ንም ፤ 6: በውኃ ፡ ላይ ፡ በመብረቅና ፡ በነጐድጓድ ፡ ላይ፣ የተሾሙ ፣ መላክአክትንም ፣ በነፉሰት ፡ ላይ።",
