    (2, 14, "Uy 8፤ የሚያመሰግኑ ፡ መላእክት ፡ ሁሉና ፡ መላእክተ የማ ገጽ ፡ ሁሉ ፡ እነዚህ ፡ ሁለቱ ፡ ብዙ ፡ ወገኖች፡ እኛ | ናቸው።"),
