    (3, 5, ". B፣ በተፈጠረበት ፡ ምድር ፡ ለአዳም ፡ አርበ ፡ ቀን፡ ከተፈጾመለት ፡ በኋላ ፡ ይገዛትም ፡ ይጠብቃ | ትም ፣ ዘንድ ፣ ወደ ፡ ገነት ፡ አስገበነው።"),
