    (5, 25, "| ብ፤፤ ስለዚህ ፡ ነገር ፡ ቡበዔውንና ፡ የወሩን ፡ መባቻ ፡ በዓሉንና ፡ ጊዜውንም ፡ ይስታሉ ፣ ከሰበው፡ሁሉ፡ ጋር ፡ ብርንዶውን ፡ ሁሉ ፡ ይበላሉ።"),
