        "ቋ፣ ከወፎችም ፡ ፊት ፡ የተነሣ ፡ ዓመቶች ፡ ድርቅ ፡ | ይሆኑ ፡ ጀመር ፤ የአንጨቱንም ፡ ፍሬ ፡ ሁሉ | ከዛፎች ፡ ላይ ፡ እየለቀሙ ፡ ይበሉ ፡ ነበር ፤ በዘ | መናቸው ፡ ከምድር ፡ ፍሬ ሁሉ ፣ ጥቁትም | ማዳን ፡ ቢችሉ ፡ በጽኑ ፡ ኃይል ፡ ነበር = በሠ ላሳ ፡ ዘጠኝኛው ፡ ኢዮቤልዩ ፡ በሁለተኛው ፡ ሱባዔ ፡ በመጀመሪያው ፡ ዓመት ፡ ታራ፡ ሚስት | አገበ።",
