        "¢« ሣ፣ ሰማይን ፡ የፈጠረ ፥ በምድር ፡ ላይ ፣ ዝናብ ፡ በበ ለዘር ፡ ል ፡ ለመከር ፡ የሚሰጥ = በምድር ፡ አሉ ላይ ፡ ሁሉን ፡ የሚያደርግ + ሁሉን ፡ በቃሉ ከ የፈጠረ ፥ ከፊቱ ፡ የሰው ፡ ሁሉ ፡ ዶግንነት ፡ ይ የሚገኝ ፡ አግዚአብሔርን ፡ አምልኩ።",
