    (8, 19, "C ጎኝ፣ በሥስተኛው ፡ ሱባኤ ፡ በቁጠር ፡ በሦስተ በ ቻው ፡ ዓመት ፡ ወንድሙ ፡ አራን ፡ ሚስት ፡ በ አገበ።"),
