        12,
        16,
        "የምትወደውን ፡ ልጅህን! | ይስሐቅን ፡ ይዘህ ፡ ከፍ ፣ ወዳለች • ተራራ | ሂድ ፣ አኔ • ከምነግርህ ፡ ከተራሮች ፡ ወደ ፡ አን | ዲቱ ተራራ ፣፡ አውጣው • አለው።",
