    (12, 25, "6 ሾር፡ አብርሃምም ፡ አልቅሶ ፡ ይቀብራት ፡ ዘንድ ፡ ክቆ ሄደ።"),
    (12, 26, "ልቡናው ፡ ይታገሥ ፡ አንደ ፡ ሆነ ፡ አንዳ ያዕ ሁም ፡በጸፉ ፡ በተናገረው ፡ነገር፡ቸል፡ አይልም ወ እንደ ፡ ሆነ ፡ ፈተንነው።"),
