    (13, 9, "የታመነ፡ የሚ አግ ታገሥ ፡ ሆኖ፡ ተገኝቶአልና ፡ በሰማይ ፡ ጽላት፡ በረ የእግዚአብሔር ፡ ወዳድ ፡ ተብሎ ፡ ተጻፈ።"),
