        13,
        10,
        "ለያ! ቋኝ፤ በአራተኛው ፡ ዓመት ፡ ለልጁ ፡ ለይስሐቅ፡ሟስ የል ትን ፣ አጋበው + ስምዋም ፡ ርብቃ ፡ ይበላል ፣ ኖክ ይህችውም ፡ የአብርሃም ፡ ወንድም ፡ የፍናከር ፡ በራ ልፁ ፡ የሚሆን ፡ የበቱኤል ፡ ልጅና ፡ የላበ ፡ ጽና እአግት ፡ናት።",
