        "መንፈስ እ ..- ቅዱስን ፡ አሳድርብኝ ፡ አለች = ቴ 181 ያንጊዚም ፡ መንፈስ ፡ ቅዱስ ፡ ወርዶ፡በአንደበ ሐ ትዋ ፣ አናገራት + ሁለቱን ፡ አጆችዋንም ፡ በያ ነበ ዕቁብ ፡ ራስ ፡ ላይ ፡ አኖረች።",
