    (27, 14, "አንተን ፡ ትቶ ፡ ለየዕቆብ ፡ አለቅነትን ፡ ለምን ፡ ስጠው ? ብለው ፡ ከአበታቸው ፡ ጋር ፡ ተከራ ከሩ።"),
    (27, 15, "፲8፤ አኔ ፡ብዙርናዬን ፡ በትንሽ ፣ ምስር ፡ንፎሮ ፡ ስጫ ለሁና ፣ ስለዚህ ፡ ነው ፣ አላቸው።"),
    (27, 16, "፲ደ፤ በልቶ ፡ ሊመርቀኝ ፡ አጃ ፡ አመጣለት ፡ ዘንድ አባቴ ፡ በላከኝ ፡ ቀን ፡ በተንኮል ፡ መጥቶ፡የሚ በላውንና ፡ የሚጠጣውን ፣ ለአባቴ ፡ አቀረበ።"),
    (27, 17, "አበቴም ፡ መረቀው = አኔን ፡ ለአርቡሱ ፡ ተገዥ ፡ አደረገኝ።"),
    (27, 18, "| ፲ቓ፤ አሁንም ፡ ወንድም ፡ ከወንድሙ ፡ ጋር ፡ በክፉ፡ ነገር እንዳንፈላስንግ = ወንድም ፡ ከወንያሙ ፡።"),
    (27, 19, "ጋር ፡ በፍቅር ፡ ጾንተን ፡ አንድንኖር = ሥራች ንንም ፡ እአንዳናጠፋ ፥ አበታችን ፡ አኔና ፡ አር ቡን ፣ አማለን ፡ አሳባቸው።"),
    (
        27,
        20,
        "| ፲፮፤ ከአርሱ፡ ጋር፡ፍቅርን፡ለማድረግ፡አንሰማህም፣ ከአርሱ ፡ ኃይል ፡ የአኛ ፣ ኃይል ፡ ይጸናልና = አኛም ፡ ከአርሱ ፡ አንበረታለንና ፡ ወደ ፡ አርሱ | ሄደን ፡ አንገድለዋለን ፥ ልጆቹንም ፣ አንገድላ ) ለን ፡ አሉት።",
    ),
    (
        27,
        21,
        "ከእና ፡ ጋር ፡ ክልኞኾድህ ፡ በአን ተም ፡ ላይ ፡ ክፉ ፡ ነገር ፡ አናደርግብሃለን = 30: አሁንም ፡ ከማን ፤ ወደ ፡ ፍልስጥኤምና ፣ ወደ | ስራም ፡ ወደ ፣ አሞንና ፡ ወደ ፡ ሞዓብ ፡ ልከን በሰልፍ ፡ የሚመክቱ ፣ የተመረጡ ፡ ሰዎችን።",
    ),
    (27, 22, "| ለራሳችን ፡ አንምረጥ ፣ 19: ወደ ፡ እርሱ ፡ ሄደን ፡ ከአርሱ ፡ ጋር ፡ አንዋጋ ፣ | ኃይል ፡ ሰያደርግ ፡ አናጥፋው ፡ ኣሉት።"),
    (
        27,
        23,
        "| ጽ፤ አበታቸውም ፡— አትሂዱ ፥ በፊቱ ፡ አንዳት ጠፉ፤ ከአርሱ ፡ ጋር ፥ ጠብን ፣ አታድርጉ ፣ አላ | ጽይ፤ ከልድነትህ፡ ጀምሮ ፡ ሥራህ፡ ይህ፣፡ ብቻ ፡ ነውን? | | አንተ ፣ አንገትህን ፡ ወደ ፡ ቀንበሩ ፡ አገዛዙ ፡፣ ታገ | በለህ ፤ አኛስ፡ ይህን ፡ ነገር ፡ አንሰማም ፡አሉት።",
    ),
    (
        27,
        24,
        "| ጽዩ፤ ወደ ፡ አበታቸው ፡ ወዳጅ ፡ ወደ ፡ አዱራምና፡ ወደ ፡ አራም ፣ ልከው ፡ የተመረጡ ፡ አርበኞች ንና ፡ ጠበኞች ፡ የሚሆኑ ፡ ሺህ ፡ ሰዎችን ፡ ከአ ነርሱ ፡ ጋር ፡ ተወዳጁ።",
    ),
    (
        27,
        25,
        "ሾ፻፫፤ ከተወዳጂአቸው ፡ከአሞን፡ ልጆችና ፡ ከሞዓብ ልጆች ፡ የተመረጡ ፡ ሺህ ፡ አርበኞች ፣ | ፳ጽፀ፤ ከፍልስጥኤም ፣ የተመረጡ ፡ ሺህ ፡ አርበኞች ፣ ቋጽደ፤ ከኰኮራውስና ፡ ከኤዶምም ፡ የተመረጡ ፣ ሲህ አርበኛች ፣፤ | - ጽጀ፤ ከኬጤዎንም ፡ ጽኑዓን ፡ የሆኑ ፡ አርበኛች ፡ ወደ ፡ አርቡ ፡ መጡ።",
    ),
    (27, 26, "| ቋ፮፤ .አበታቸውንም ~- መጥተህ ፡ ምራቸው ፣ ይህ፡ ክልሆን ፡ እንገድልሃለን ፡ አሉት = ወደ ፡ ወን ደሙ ፡ ወደ ፡ ያዕቆብ ፡ ሲ.መራቸው ፡ ይሄድ ፡።"),
    (27, 27, "ዘንድ ፣ ልጆቹ ፡ አንደ ፡ ተበሩራቱበት ፡ ልጆቹን በየ ፡ጊዘ, ፡ ፈጽሞ ፡ ቍጣን ፡ ተመላ።"),
    (
        28,
        1,
        "ሾጆ፣ ከዚህ ፡ በኋላ ፡ በልቡ ፡የተስወረ፡ክፋትን፡ሁሉ፡ - በወንድሙ ፡ በያፅቋቆብ ፡ አስበ = ነገር ፡ ግን ፡ በለ፡ ዘመት ፣ ሁሉ ፡ በወንድሙ ፡ በያዕቆብ ፡ ላይ ፡ የኢትዮያ ኦርቶዶክስ ተዋሕዶ ቤተ | 975 መጽሐፈ፡ ኩፋ | ትጠፋለህ ፥ ልጆችህም ፡ ይጠፋሉ።",
    ),
    (28, 2, "ለአንተ ፡ L | ፍቅር ፡ አንድነት ፡ አይደረግልህም።"),
    (28, 3, '( ጓ፪፤ ያን፡ጊዜም ፡ ያዕቁብ ፡ በአርሱ ፡ ልቡናውን ፡፣አን { | ዳስረጨኬከነ + ይገድለውያም ፡ ዘንድ ፡ በፍጹም ፡ " ልቡናው ፡ አንዳሰበ ፡ አየ።'),
    (
        28,
        4,
        "| ሣ፫የ፤፣ በጦር ፡ ወግቱቶ ፡ ወደሚገድለው ፡ ሰው ፣ አሪያ [ ፈጥና ፡ አንዲወጣ ፥ ከአርሱም ፡ እአንዳሬክ ሽ + | ሕሙ ፣፡ ፈጥኖ ፣ ወጣ = [ ሣዳ፱ፀ፤ ያን ፡ ጊዚም ፡ በሪየዎቹንና ፡ ወገኖቹን ፡ ወዳኝ | ቹንም ፡ ሁሉ ፡ ይከቡት ፡ ዘንድ ፡ አዘዘ።",
    ),
    (
        28,
        5,
        "| ሣፎ፤ ከነዚህ ፡ በኋላ ፡ ይሁዳ ፡ አበቱ ን ፡ ያዕቆብን ፡ ተና | ገረው ~~ አበቱ ፡ ሆይ ቀስትህን ፡ ሳብ = ፍላጻ | ከሀን ፡ ወርውረህ ፡ ጠላትህን ፡ ውጋ ፤ ጠላት | ህን ፡ ግደል።",
    ),
    (28, 6, "| ጣሄ፤ እኛ ፡ ወንድምህን ፡ አንገድልምና + አርሱም ፡።"),
    (28, 7, "| በአንተ ፡ ዘንድ ፡ አለና ፡ ይመስልሃልና = በአ | ኛም ፡ ዘንድ ፡ ለመክበር ፡ አንደ ፡አንተ ፡ ነውና | ኃይል ፡ ለአንተ ፡ ይሁን ፡ አለው።"),
    (28, 8, "| | ጓሂ፤ ያን፡ጊዜ ፡ ያዕቆብ ፡ ቀስቱን ፡ ስቦ ‘ፍላጻውን፣፡ ወርወር ፡ ወንድሙን ፡ ሳውን ፡ ሠግቶ ፡ ገይ | ለወ።"),
    (28, 9, "| ሣሯ፤ ዳግመኛም ፡ ፍላጻውን ፡ ወርውር ፣ የአሕዛብ ፡ ወገን ፡ የሚሆን ፣ አዱራንን ፡ የግራ ፡ ጡት ፣ | ሥሩን ፣ ወጋው ፤ አሳዶ ፡ ገይለው።"),
    (28, 10, "1: ከዚህም ፡ በኋላ ፡ እነዚያ ፡ የያዕቆብ፡ ልጆች ፡ | በሪያዎቻቸውም ፡ ተከፍለው ፡ በግምቡ ፡ዙ ሪያ በአራቱ ፡ ማዕዘን ፡ ወጡ።"),
    (28, 11, "| 2: ይሁዳ ፡ በፊት ፡ ወጣ ፣ ጋድና ፡ ንፍቻታሴምም ፡።"),
    (28, 12, "ከእርሱ ፡ ጋር ፡ ወጡ ፣ አም ፡ ብላቴናችትም ፡ ከአርሱ ፡ ጋር ነበሩ።"),
    (28, 13, "በግምቡ ፡ ግሪ. ፡ አንጻር : | ወጥተው ፡ በፊታቸው ፡ያገትን፣ሁሉ፡ገድደሉ።"),
    (28, 14, "ከእነርሱም ፡ አንድ ፡ በው ፡ ስን», ፡ ያመለጠ ፡ | የለም።"),
    (
        28,
        15,
        "የ፤ ዳንና ፡ ሴቱ ፡ አሴርም ፡ በግምቡ ፡ ምሥራቅ ፡ አንጻር ፡ ወጡ ፣ አምሳ ፡ ብላቴኖችም ፡ከእነርሱ፡ ጋር ፡ ነበሩ ፣ የአሞንና ፡ የሞዓብን ፡ አርበኛች | ወጉ።",
    ),
    (
        28,
        16,
        "2: ይሳክከርና ፡ ሮቤል ፡ዛብሎንም ፡ በግምቡ ፡ ቀኝ ፡ | ጸንጻር ፡ ወጡ ፣ አምሳ ፡ ብላቴና ችም ፡ ከአርሱ፡ | ጋር፡ነበሩ፤፣የፍልስጥኤምን፡ አርበኛች ፡ ወጉ።",
    ),
    (28, 17, "፪፡ ብንያምና ፡ ስምዖን ፡ የሮቤል ፡ ልድ ፡ ኤናክ ፡ በግምቡ ፡ ምዕራብ ፡ አንጻር ፡ ወጡ።"),
    (28, 18, "አምሳ ብላናኖችም ፡ ከአነርሱ ፡ ጋር ፡ ነበሩ።"),
    (28, 19, "ከኮሬዎ ንፍ ፡ ከኤዶም ፣ ጽኑዓን ፡ አርበኛች ፡ የሚሆኑ፡ አራት ፡ መቶ ፡ ሰዎችን ፡ገደሉ።"),
    (28, 20, "ስድስት ፡ መቶ ሰዎች ፡ ዘሹ ፣ አራቱ ፡ የዔሳው ፡ ልጆ ትም ፡ ከአ ነርሱ ፡ ጋር፡ቨሹ።"),
    (
        28,
        21,
        "6: አበታቸው ፡ በከረብታው ፡ ላይ ፡ ሞቶ፡ አንደ ወደቀ ፡ትተውት ፡ ዘዙ = ይህችውም ፡ በጸ ራም ፣ ያለች ፡ ኮረብታ ፡ ናት ! የያዕቁብም ፡ ልጆች ፡ በኋላቸው ፡ ተከትለው ፡ አስክ ፡ ሴድር፡ ተራራ ፡ ድረስ ፡ አሳደዱአቸው።",
    ),
    (28, 22, "የኢት ዮጵያ ኦርቶዶክስ ተዋሕዶ ቤች ቆይ፣ የግብጹም ፡ በው ፡ አግዚአብሔር ፡ ከዮሴፍ።"),
    (28, 23, "ጋር ፡ በረድኤት ፡ አንዳለ የሠራውንም ፣ ሥራ፡ ሀሉ ፡ አግዚአብሔር ፣ አንዲያቀናለት ፣ አይቶ አልና ፡ ሁሉን ፡ በሬቱ ፡ ተወ።"),
    (28, 24, "፫ዩ፣ ዮሴፍ ፡ ግን ፡ መልኩ ፡ የማረ ፡ እጅግ ፡ ደመ ግቡ ፣ ነበረ።"),
    (28, 25, "ሽ፫፤ የጌታውም ፡ ሚስት ፡ ዓይኖችዋን ፡ አቅንታ ፡ የዮሴፍን ፡ አየችው።"),
    (28, 26, "ወደደችው ፣ ይደርስበ ትም ፡ ዘንድ ፡ ለመነትው ፤ አርሱ ፡ ግን ፡ ሰውነ ቱን ፡ አልስጣትም።"),
    (
        28,
        27,
        "፳8፤ አግዚአብሔርንም ፡ አስበው ፣ በል ፡ በላት ሴት ፡ ማንም ፡ ማን ፡ ሰበው ፡ አንዳይሰ.ስን ፡ ከአ ብርሃም , ቃል ፡ አግኝቶ ፡ አበቱ ፡ ያዕቆብ ፡ የተ ናገራቸውን ፡ ነገሮች ፡ አስበ።",
    ),
    (28, 28, "በሰማይ ፡ልዑ-ል፡ በሆን ፡ በአግዘ አብሔርም ፣ ፊት ፡ የሞት ፡ ቅጣ ትም ፡ አንዳለበት ፡ አሰበ።"),
