    (29, 11, "ሞ .፲{፣ የግብጽ ፡ እገር ፡ ስለ ፡ዮሴፍ ፡ ደግነት ፡ በፈርያፆያን፡ በ | ፊት ፡ ተስማምታ ፡ኖረች።"),
